import * as React from "react";
import { headers } from "next/headers";

/**
 * Operations Admin Portal layout (`/ops-portal/*`).
 *
 * Reads the per-request `x-nonce` header generated by `src/proxy.ts` so all
 * admin routes are dynamically rendered with a per-request CSP nonce and
 * zero static caching.
 */
export default async function OpsPortalLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const headerList = await headers();
  const nonce = headerList.get("x-nonce") ?? undefined;

  return (
    <div data-csp-mode="nonce" data-nonce-present={nonce ? "true" : "false"}>
      {children}
    </div>
  );
}
